_map:
if (item.vehicle_id && item.lng != null && item.lat != null && item.crowding > 0) {
emit(item.vehicle_id, {
  lng: item.lng,
  lat: item.lat,
  crowding: item.crowding,
  _ts: item._ts || 0
});
}

_reduce:
var best = values[0], i, v;
for (i = 1; i < values.length; i++) {
  v = values[i];
  if ((v._ts || 0) > (best._ts || 0)) {
    best = v;
  }
}
emit(best);

_finalize:
var cells = {}, row, d, gx, gy, key, c, out = [];
reduction.forEach(function (row) {
  if (!row || row.length < 2 || !row[1]) {
    return;
  }
  d = row[1];
  if (d.lng == null || d.lat == null) {
    return;
  }
  gx = Math.floor(d.lng * 400);
  gy = Math.floor(d.lat * 400);
  key = gx + ',' + gy;
  if (!cells[key]) {
    cells[key] = {
      lng: (gx + 0.5) / 400,
      lat: (gy + 0.5) / 400,
      crowdingSum: 0,
      vehicles: 0,
      maxCrowding: 0
    };
  }
  c = cells[key];
  c.crowdingSum += d.crowding || 0;
  c.vehicles += 1;
  c.maxCrowding = Math.max(c.maxCrowding, d.crowding || 0);
});
Object.keys(cells).forEach(function (k) {
  c = cells[k];
  c.avgCrowding = c.vehicles ? c.crowdingSum / c.vehicles : 0;
  out.push([k, c]);
});
emit(out);
